import pandas as pd

def sum_daily_odd_even(transactions: pd.DataFrame) -> pd.DataFrame:
    if transactions.empty:
        return pd.DataFrame(columns=['transaction_date', 'odd_sum', 'even_sum'])

    transactions['odd_sum'] = transactions['amount'].where(transactions['amount'] % 2 != 0, 0)
    transactions['even_sum'] = transactions['amount'].where(transactions['amount'] % 2 == 0, 0)

    result = transactions.groupby('transaction_date', as_index=False)[['odd_sum', 'even_sum']].sum()
    return result.sort_values(by='transaction_date', ascending=True)
